import os,re,subprocess,sys
moves={}
for f in subprocess.check_output(['git','ls-files','lib'],text=True).split():
    if f.count('/')!=1: continue
    b=f[4:]
    if b.startswith('import-'): moves[f]='lib/import/'+b[7:]
    elif b.startswith('csv.') or b.startswith('xlsx-scope') or b.startswith('exceljs-dependency'): moves[f]='lib/import/'+b
    elif b.startswith('dashboard'): moves[f]='lib/finance/'+b
for o,n in moves.items():
    assert not os.path.exists(n),n
os.makedirs('lib/import',exist_ok=True)
for o,n in moves.items(): subprocess.check_call(['git','mv',o,n])
strip=lambda p: re.sub(r'\.(tsx?|mjs)$','',p)
mod={strip(o):strip(n) for o,n in moves.items()}
inv={v:k for k,v in mod.items()}
files=[f for f in subprocess.check_output(['git','ls-files'],text=True).split() if re.search(r'\.(tsx?|mjs|js)$',f) and not f.startswith('app/.well-known')]
pat=re.compile(r'''(["'])((?:@/|\.\.?/)[^"'\n]+)\1''')
for f in files:
    s=open(f,encoding='utf8').read()
    oldself=inv.get(strip(f),strip(f)) # original location for resolving relative specifiers
    def rep(m):
        spec=m.group(2)
        if spec.startswith('@/'): tgt=spec[2:]
        else: tgt=os.path.normpath(os.path.join(os.path.dirname(oldself),spec)).replace('\\','/')
        if tgt in mod: return m.group(1)+'@/'+mod[tgt]+m.group(1)
        if not spec.startswith('@/') and f!=oldself+os.path.splitext(f)[1] and strip(f)!=oldself:
            # file moved: relative spec to unmoved target must be re-pointed
            return m.group(1)+'@/'+tgt+m.group(1) if os.path.exists(tgt+'.ts') or os.path.exists(tgt+'.tsx') or os.path.isdir(tgt) else m.group(0)
        return m.group(0)
    t=pat.sub(rep,s)
    if t!=s: open(f,'w',encoding='utf8',newline='').write(t)
EOF
